def minPath(grid, k):
    N = len(grid)

    # Directions for moving to adjacent cells (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, path, remaining_steps):
        if remaining_steps == 0:
            return path[:]

        # Early termination: if we already have a better path
        current_path = path[:]
        min_val = float('inf')
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                min_val = min(min_val, grid[nx][ny])

        # If we can't improve the lexicographic order by continuing,
        # return a large value to indicate this path is not optimal
        if len(path) > 0 and path[-1] < min_val:
            return None

        best_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                # Add the new cell to the path
                path.append(grid[nx][ny])
                result = dfs(nx, ny, path, remaining_steps - 1)
                path.pop()

                if result is not None:
                    if best_path is None or result < best_path:
                        best_path = result

        return best_path

    # Try starting from each cell
    min_result = None
    for i in range(N):
        for j in range(N):
            path = [grid[i][j]]
            result = dfs(i, j, path, k - 1)
            if result is not None:
                if min_result is None or result < min_result:
                    min_result = result

    return min_result
