def minPath(grid, k):
    n = len(grid)

    best_path = None

    def dfs(r, c, path):
        nonlocal best_path

        # Pruning: if current partial path is already worse than best, stop
        if best_path is not None and len(path) <= k:
            for idx in range(len(path)):
                if idx < len(best_path) and path[idx] > best_path[idx]:
                    return  # Current path is lexicographically larger

        if len(path) == k:
            if best_path is None or path < best_path:
                best_path = list(path)
            return

        # Try all adjacent cells
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                path.append(grid[nr][nc])
                dfs(nr, nc, path)
                path.pop()

    # Sort cells by value to explore better starting points first
    cells = []
    for i in range(n):
        for j in range(n):
            cells.append((grid[i][j], i, j))
    cells.sort(key=lambda x: x[0])

    for val, r, c in cells:
        if best_path is not None and grid[r][c] >= max(best_path):
            continue

        dfs(r, c, [grid[r][c]])

    return best_path
