    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        return s[::-1]  # Reverse the entire string

    result = []
    for char in s:
        if char.isalpha():
            # Flip case of letters
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            # Keep non-letters as is
