def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n == 1:
        return 1

    # If n is even, n/2 is the largest proper divisor
    if n % 2 == 0:
        return n // 2

    # For odd numbers, check from sqrt(n) down to find the largest divisor
    for i in range(int(n**0.5), 0, -1):
        if n % i == 0:
            return n // i

    return 1  # fallback (shouldn't reach here for n > 1)
```

